"""Slug helpers imported by the report CLI."""

def collapse_title(text):
    parts = []
    for chunk in text.lower().split():
        piece = "".join(ch for ch in chunk if ch.isalnum())
        if piece:
            parts.append(piece)
    return "-".join(parts)

def build_report_slug(title, owner):
    return collapse_title(f"{owner} {title}")

"""Batch sizing for the intake worker."""

POLL_INTERVAL_SECONDS = 15
BATCH_SIZE = 8

def take_batch(items, size=BATCH_SIZE):
    if size < 1:
        return []
    return list(items[:size])

def preview(items):
    return take_batch(items)

if __name__ == "__main__":
    preview(["a", "b", "c"])

